// Generated by Cypress Author on 2026-09-03
describe('Recipe List Page', () => {
  beforeEach(() => {
    // Mock the recipes API
    cy.intercept(
      'GET',
      '/api/recipes?page=1&pageSize=12&method=recipes&category=&subcategory=&rating=',
      {
        statusCode: 200,
        body: {
          items: Array.from({ length: 12 }).map((_, i) => ({
            id: `recipe-${i}`,
            slug: `recipe-${i}`,
            title: `Test Recipe ${i}`,
            description: `Description ${i}`,
            image: `/images/recipe-${i}.jpg`,
          })),
          total: 24, // 2 pages
        },
      },
    ).as('getRecipesPage1');

    cy.intercept(
      'GET',
      '/api/recipes?page=2&pageSize=12&method=recipes&category=&subcategory=&rating=',
      {
        statusCode: 200,
        body: {
          items: Array.from({ length: 12 }).map((_, i) => ({
            id: `recipe-${12 + i}`,
            slug: `recipe-${12 + i}`,
            title: `Test Recipe ${12 + i}`,
            description: `Description ${12 + i}`,
            image: `/images/recipe-${12 + i}.jpg`,
          })),
          total: 24,
        },
      },
    ).as('getRecipesPage2');

    // Also need to mock index data for subcategories and breadcrumbs
    cy.intercept('GET', '/api/recipe-index', {
      statusCode: 200,
      body: {
        categoriesList: [],
        methodsList: [],
        holidays: [],
        specialDiets: [],
        bestRecipes: [],
        ingredients: [],
      },
    }).as('getIndexData');
  });

  it('should render recipe grid and handle pagination', () => {
    cy.visit('/recipes');
    cy.wait('@getIndexData');
    cy.wait('@getRecipesPage1');

    // Check recipe rendering
    cy.get('mat-card').should('have.length', 12);
    cy.get('h3').contains('Test Recipe 0').should('be.visible');

    // Check pagination controls
    cy.get('.recipe-pagination').should('be.visible');

    // Navigate to page 2
    cy.get('.recipe-pagination a').contains('2').click({ force: true });

    // Verify page 2 recipes loaded
    cy.wait('@getRecipesPage2');
    cy.url().should('include', '/recipes/page/2');
    cy.get('h3').contains('Test Recipe 12').should('be.visible');
  });

  it('should utilize fast client-side caching when navigating back', () => {
    cy.visit('/recipes');
    cy.wait('@getRecipesPage1');

    // Navigate to page 2
    cy.get('.recipe-pagination a').contains('2').click({ force: true });
    cy.wait('@getRecipesPage2');

    // Clear network alias intercepts to ensure we don't hit the network for page 1
    cy.intercept(
      'GET',
      '/api/recipes?page=1&pageSize=12&method=recipes&category=&subcategory=&rating=',
      cy.spy().as('cachedRequest'),
    );

    // Navigate back to page 1
    cy.get('.recipe-pagination a').contains('1').click({ force: true });

    // UI should show page 1 items instantly without network request
    cy.get('h3').contains('Test Recipe 0').should('be.visible');

    // Assert that the network request was NOT made (caching worked)
    cy.get('@cachedRequest').should('not.have.been.called');
  });
});
